import 'dart:io';

import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:flutter_svg/flutter_svg.dart';

import '../app_config.dart';
import '../l10n/l10n.dart';
import '../providers/desktop/current_desktop_menu_item.dart';
import '../services/network_privacy.dart';
import '../themes/stack_colors.dart';
import '../utilities/assets.dart';
import '../utilities/text_styles.dart';
import '../widgets/adaptive_page.dart';
import '../widgets/desktop/desktop_tor_status_button.dart';
import '../widgets/desktop/living_stack_icon.dart';
import 'desktop_menu_item.dart';
import 'settings/settings_menu.dart';

enum DesktopMenuItemId { myStack, addressBook, settings, support, about }

class DesktopMenu extends ConsumerStatefulWidget {
  const DesktopMenu({
    super.key,
    this.onSelectionChanged,
    this.onSelectionWillChange,
  });

  final void Function(DesktopMenuItemId)? onSelectionChanged;
  final void Function(DesktopMenuItemId)? onSelectionWillChange;

  @override
  ConsumerState<DesktopMenu> createState() => _DesktopMenuState();
}

class _DesktopMenuState extends ConsumerState<DesktopMenu> {
  static const expandedWidth = 240.0;
  static const minimizedWidth = 72.0;

  final Duration duration = const Duration(milliseconds: 250);
  late final List<DMIController> controllers;
  late final DMIController torButtonController;

  double _width = expandedWidth;
  bool get _isMinimized => _width < expandedWidth;

  /// Whether the window is narrow enough to fold the menu. Set on the first
  /// build. After that the menu follows the window only when it crosses the
  /// line, so that the button keeps working at any size.
  bool? _narrowWindow;

  void updateSelectedMenuItem(DesktopMenuItemId idKey) {
    widget.onSelectionWillChange?.call(idKey);

    ref.read(currentDesktopMenuItemProvider.notifier).state = idKey;

    widget.onSelectionChanged?.call(idKey);
  }

  void toggleMinimize() {
    final expanded = _width == expandedWidth;

    for (final e in controllers) {
      e.toggle?.call();
    }

    torButtonController.toggle?.call();

    setState(() {
      _width = expanded ? minimizedWidth : expandedWidth;
    });
  }

  @override
  void initState() {
    controllers = [
      DMIController(),
      DMIController(),
      DMIController(),
      DMIController(),
      DMIController(),
      DMIController(),
    ];

    torButtonController = DMIController();

    super.initState();
  }

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    final narrow = MediaQuery.sizeOf(context).width < DesktopFit.foldMenuWidth;
    if (narrow == _narrowWindow) return;
    final firstBuild = _narrowWindow == null;
    _narrowWindow = narrow;
    if (firstBuild) {
      _width = narrow ? minimizedWidth : expandedWidth;
    } else if (narrow != _isMinimized) {
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (mounted && _narrowWindow != _isMinimized) toggleMinimize();
      });
    }
  }

  @override
  void dispose() {
    for (final e in controllers) {
      e.dispose();
    }
    torButtonController.dispose();

    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final short = DesktopFit.short(context);
    return Material(
      color: Theme.of(context).extension<StackColors>()!.popupBG,
      child: AnimatedContainer(
        width: _width,
        duration: duration,
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.center,
          children: [
            SizedBox(height: short ? 12 : 25),
            AnimatedContainer(
              duration: duration,
              width: _width == expandedWidth ? (short ? 44 : 70) : 32,
              child: LivingStackIcon(onPressed: toggleMinimize),
            ),
            SizedBox(height: short ? 2 : 10),
            AnimatedOpacity(
              duration: duration,
              opacity: _width == expandedWidth && !short ? 1 : 0,
              child: SizedBox(
                height: short ? 0 : 28,
                child: Text(
                  AppConfig.appName,
                  style: STextStyles.desktopH2(context)
                      .copyWith(fontSize: 18, height: 23.4 / 18),
                ),
              ),
            ),
            if (NetworkPrivacy.available.isNotEmpty) const SizedBox(height: 5),
            if (NetworkPrivacy.available.isNotEmpty)
              AnimatedContainer(
                duration: duration,
                width: _width == expandedWidth
                    ? _width -
                          32 // 16 padding on either side
                    : _width - 16, // 8 padding on either side
                child: DesktopTorStatusButton(
                  transitionDuration: duration,
                  controller: torButtonController,
                  isExpandedInitially: !_isMinimized,
                  onPressed: () {
                    ref.read(currentDesktopMenuItemProvider.notifier).state =
                        DesktopMenuItemId.settings;
                    ref
                        .read(selectedSettingsMenuItemStateProvider.notifier)
                        .state = DesktopSettingsPage
                        .networkPrivacy
                        .index;
                  },
                ),
              ),
            SizedBox(height: short ? 12 : 40),
            Expanded(
              child: AnimatedContainer(
                duration: duration,
                width: _width == expandedWidth
                    ? _width -
                          32 // 16 padding on either side
                    : _width - 16, // 8 padding on either side
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.stretch,
                  children: [
                    Expanded(
                      child: SingleChildScrollView(
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.stretch,
                          children: [
                            DesktopMenuItem(
                              key: const ValueKey('myStack'),
                              duration: duration,
                              icon: const DesktopMyStackIcon(),
                              label: l10n.desktopMyWallets,
                              value: DesktopMenuItemId.myStack,
                              onChanged: updateSelectedMenuItem,
                              controller: controllers[0],
                              isExpandedInitially: !_isMinimized,
                            ),
                            const SizedBox(height: 2),
                            DesktopMenuItem(
                              key: const ValueKey('addressBook'),
                              duration: duration,
                              icon: const DesktopAddressBookIcon(),
                              label: l10n.desktopAddressBook,
                              value: DesktopMenuItemId.addressBook,
                              onChanged: updateSelectedMenuItem,
                              controller: controllers[1],
                              isExpandedInitially: !_isMinimized,
                            ),
                            const SizedBox(height: 2),
                            DesktopMenuItem(
                              key: const ValueKey('settings'),
                              duration: duration,
                              icon: const DesktopSettingsIcon(),
                              label: l10n.settingsTitle,
                              value: DesktopMenuItemId.settings,
                              onChanged: updateSelectedMenuItem,
                              controller: controllers[2],
                              isExpandedInitially: !_isMinimized,
                            ),
                            const SizedBox(height: 2),
                            DesktopMenuItem(
                              key: const ValueKey('support'),
                              duration: duration,
                              icon: const DesktopSupportIcon(),
                              label: l10n.settingsSupport,
                              value: DesktopMenuItemId.support,
                              onChanged: updateSelectedMenuItem,
                              controller: controllers[3],
                              isExpandedInitially: !_isMinimized,
                            ),
                            const SizedBox(height: 2),
                            DesktopMenuItem(
                              key: const ValueKey('about'),
                              duration: duration,
                              icon: const DesktopAboutIcon(),
                              label: l10n.settingsAbout,
                              value: DesktopMenuItemId.about,
                              onChanged: updateSelectedMenuItem,
                              controller: controllers[4],
                              isExpandedInitially: !_isMinimized,
                            ),
                          ],
                        ),
                      ),
                    ),
                    if (!Platform.isIOS) ...[
                      const SizedBox(height: 16),
                      DesktopMenuItem(
                        key: const ValueKey('exit'),
                        duration: duration,
                        labelLength: 146,
                        icon: const DesktopExitIcon(),
                        label: l10n.desktopExit,
                        value: 7,
                        onChanged: (_) {
                          exit(0);
                        },
                        controller: controllers[5],
                        isExpandedInitially: !_isMinimized,
                      ),
                    ],
                  ],
                ),
              ),
            ),
            Row(
              children: [
                const Spacer(),
                IconButton(
                  splashRadius: 18,
                  onPressed: toggleMinimize,
                  icon: SvgPicture.asset(
                    Assets.svg.minimize,
                    height: 12,
                    width: 12,
                  ),
                ),
              ],
            ),
          ],
        ),
      ),
    );
  }
}
